INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q139808', 'Battle of the Maureaco Fields', 'The Battle of the Catalaunian Plains (or Fields), also called the Battle of the Campus Mauriacus, Battle of Châlons, Battle of Troyes or the Battle of Maurica, took place on 20 June 451 AD, pitting a coalition led by the Roman general Flavius Aetius and the Visigothic king Theodoric I against the Huns and their vassals, commanded by their king, Attila. It proved to be one of the last major military operations of the Western Roman Empire, although Germanic foederati composed the majority of the coalition army.', 451, 6, 20, NULL, NULL, NULL, 'day', '20 June 451', 77, 'https://en.wikipedia.org/wiki/Battle_of_the_Catalaunian_Plains'),
  ('Q851504', 'Battle of Vouille', 'The Battle of Vouillé (from Latin Campus Vogladensis) was a battle in the Franco-Gothic War and was fought in the northern marches of Visigothic territory, at Vouillé, near Poitiers (Gaul), around spring 507 between the Franks, commanded by Clovis, and the Visigoths, commanded by Alaric II. The Franks'' victory resulted in their conquest of Gallia Aquitania and the death of Alaric II.', 507, NULL, NULL, NULL, NULL, NULL, 'year', '507', 70, 'https://en.wikipedia.org/wiki/Battle_of_Vouill%C3%A9'),
  ('Q173077', 'Battle of Tours', 'The Battle of Tours, also called the Battle of Poitiers and the Battle of the Highway of the Martyrs (Arabic: معركة بلاط الشهداء, romanized: Maʿrakat Balāṭ ash-Shuhadā''), was fought on 10 October 732, and was an important battle during the Umayyad invasion of Gaul. It resulted in victory for the Frankish and Aquitanian forces, led by Charles Martel, over the invading Umayyad forces, led by Abd al-Rahman al-Ghafiqi, governor of al-Andalus.', 732, 10, 10, NULL, NULL, NULL, 'day', '10 October 732', 80, 'https://en.wikipedia.org/wiki/Battle_of_Tours'),
  ('Q51657', 'Albigensian Crusade', 'The Albigensian Crusade (French: Croisade des albigeois), also known as the Cathar Crusade (1209–1229), was a military and ideological campaign initiated by Pope Innocent III to eliminate Catharism in Languedoc, what is now southern France. The Crusade was prosecuted primarily by the French crown and promptly took on a political aspect.', 1209, NULL, NULL, 1229, NULL, NULL, 'year', '1209–1229', 77, 'https://en.wikipedia.org/wiki/Albigensian_Crusade'),
  ('Q27759', 'Battle of Crécy', 'The Battle of Crécy took place on 26 August 1346 in northern France between a French army commanded by King Philip VI and an English army led by King Edward III. The French attacked the English while they were traversing northern France during the Hundred Years'' War, resulting in an English victory and heavy loss of life among the French. The English army had landed in the Cotentin Peninsula on 12 July.', 1346, 8, 26, NULL, NULL, NULL, 'day', '26 August 1346', 75, 'https://en.wikipedia.org/wiki/Battle_of_Cr%C3%A9cy'),
  ('Q201692', 'Battle of Poitiers', 'The Battle of Poitiers was fought on 19 September 1356, during the Hundred Years'' War, between a French army commanded by King John II and an Anglo-Gascon force under Edward, the Black Prince. It took place in western France, 5 miles (8 km) south of Poitiers, when approximately 14,000 to 16,000 French attacked a strong defensive position held by 6,000 Anglo-Gascons.', 1356, 9, 19, NULL, NULL, NULL, 'day', '19 September 1356', 75, 'https://en.wikipedia.org/wiki/Battle_of_Poitiers'),
  ('Q188495', 'Battle of Agincourt', 'The Battle of Agincourt (; French: Azincourt [azɛ̃kuʁ]) was an English victory in the Hundred Years'' War (1337–1453). It took place on 25 October 1415 (Saint Crispin''s Day) near Azincourt, in northern France.', 1415, 10, 25, NULL, NULL, NULL, 'day', '25 October 1415', 78, 'https://en.wikipedia.org/wiki/Battle_of_Agincourt'),
  ('Q392213', 'Siege of Orléans', 'The siege of Orléans (12 October 1428 – 8 May 1429) marked a turning point of the Hundred Years'' War between France and England. The siege took place at the pinnacle of English power during the later stages of the war, but was repulsed by French forces inspired by the arrival of Joan of Arc.', 1428, 10, 21, 1429, 5, 17, 'day', '21 October 1428 – 17 May 1429', 70, 'https://en.wikipedia.org/wiki/Siege_of_Orl%C3%A9ans_(1428%E2%80%931429)'),
  ('Q728480', 'Battle of Rocroi', 'The Battle of Rocroi, fought on 19 May 1643, was a major engagement of the Thirty Years'' War between a French army, led by the 21-year-old Duke of Enghien (later known as the Great Condé) and Spanish forces under General Francisco de Melo only five days after the accession of Louis XIV to the throne of France after his father''s death. Rocroi shattered the myth of invincibility of the Spanish tercios, the pike and shot infantry units that had dominated European battlefields for the previous 120 years.', 1643, 5, 19, NULL, NULL, NULL, 'day', '19 May 1643', 67, 'https://en.wikipedia.org/wiki/Battle_of_Rocroi'),
  ('Q221670', 'Treaty of the Pyrenees', 'The Treaty of the Pyrenees was signed on 7 November 1659 and ended the Franco–Spanish War that had begun in 1635. Negotiations were conducted and the treaty was signed on Pheasant Island, situated in the middle of the Bidasoa River on the border between the two countries, which has remained a French-Spanish condominium ever since.', 1659, 11, 7, NULL, NULL, NULL, 'day', '7 November 1659', 71, 'https://en.wikipedia.org/wiki/Treaty_of_the_Pyrenees'),
  ('Q156211', 'Treaty of Paris (1763)', 'The Treaty of Paris, also known as the Treaty of 1763, was signed on 10 February 1763 by the kingdoms of Great Britain, France and Spain, with Portugal in agreement, following Great Britain and Prussia''s victory over France and Spain during the Seven Years'' War. The signing of the treaty formally ended the conflict between France and Great Britain over control of North America (the Seven Years'' War, known as the French and Indian War in the United States), and marked the beginning of an era of British dominance outside Europe.', 1763, 2, 10, NULL, NULL, NULL, 'day', '10 February 1763', 73, 'https://en.wikipedia.org/wiki/Treaty_of_Paris_(1763)'),
  ('Q217450', 'Treaty of Paris (1783)', 'The Treaty of Paris, signed by representatives of King George III of Great Britain and representatives of the United States on September 3, 1783, officially ended the War of American Independence and recognized the Thirteen Colonies, which had been part of colonial British America, to be free, sovereign, and independent unified states. It forms one treaty out of many that are collectively named the "Peace of Paris".', 1783, 9, 3, NULL, NULL, NULL, 'day', '3 September 1783', 78, 'https://en.wikipedia.org/wiki/Treaty_of_Paris_(1783)'),
  ('Q6534', 'French Revolution', 'The French Revolution was a period resulting in the political and societal changes in France that began with the Estates General of 1789 and ended with the Coup of 18 Brumaire on 9 November 1799. Many of the revolution''s ideas are considered fundamental principles of liberal democracy, and its values remain central to modern French political discourse.', 1789, 7, 14, 1799, 11, 9, 'day', '14 July 1789 – 9 November 1799', 100, 'https://en.wikipedia.org/wiki/French_Revolution'),
  ('Q6539', 'Storming of the Bastille', 'The Storming of the Bastille (French: Prise de la Bastille [pʁiz də la bastij]), also known as Fall of the Bastille, which occurred in Paris, France, on 14 July 1789, was an act of political violence by revolutionary insurgents who attempted to storm and seize control of the medieval armoury, fortress, and political prison known as the Bastille. After four hours of fighting and 94 deaths, the insurgents were able to enter the Bastille.', 1789, 7, 14, NULL, NULL, NULL, 'day', '14 July 1789', 78, 'https://en.wikipedia.org/wiki/Storming_of_the_Bastille'),
  ('Q4411', 'Battle of Valmy', 'The Battle of Valmy, also known as the Cannonade of Valmy, was the first major victory by the army of France during the Revolutionary Wars that followed the French Revolution. The battle took place on 20 September 1792 as Prussian troops commanded by the Duke of Brunswick attempted to march on Paris.', 1792, 9, 20, NULL, NULL, NULL, 'day', '20 September 1792', 70, 'https://en.wikipedia.org/wiki/Battle_of_Valmy'),
  ('Q193547', 'Reign of Terror', 'The Reign of Terror (French: La Terreur, lit. ''The Terror'') was a period of the French Revolution when, following the creation of the First Republic, a series of massacres and numerous public executions took place in response to the Federalist revolts, revolutionary fervour, anticlerical sentiment, and accusations of treason by the Committee of Public Safety. While terror was never formally instituted as a legal policy by the convention, it was more often employed as a concept.', 1793, NULL, NULL, 1794, 7, 28, 'decade', '1790s – 28 July 1794', 80, 'https://en.wikipedia.org/wiki/Reign_of_Terror'),
  ('Q112183', 'Treaty of Amiens', 'The Treaty of Amiens (French: la paix d''Amiens, lit. ''the peace of Amiens'') was a peace treaty signed between the French First Republic, Spain and Batavian Republic on one side and the United Kingdom on the other side in 1802. Signed on 27 March in the Hôtel de Ville (City Hall) of Amiens by Joseph Bonaparte for France and Lord Cornwallis for Britain, the treaty ended the ongoing War of the Second Coalition and marked the end of the French Revolutionary Wars, which had begun in 1792.', 1802, 3, 27, NULL, NULL, NULL, 'day', '27 March 1802', 76, 'https://en.wikipedia.org/wiki/Treaty_of_Amiens'),
  ('Q690989', 'Treaty of Fontainebleau', 'The Treaty of Fontainebleau was an agreement concluded in Fontainebleau, France, on 11 April 1814 between Napoleon and representatives of Austria, Russia and Prussia. The treaty was signed in Paris on 11 April by the plenipotentiaries of both sides and ratified by Napoleon on 13 April.', 1814, 4, 11, NULL, NULL, NULL, 'day', '11 April 1814', 68, 'https://en.wikipedia.org/wiki/Treaty_of_Fontainebleau_(1814)'),
  ('Q740724', 'Treaty of Paris', 'The Treaty of Paris, signed on 30 May 1814, ended the war between France and the Sixth Coalition, part of the Napoleonic Wars, following an armistice signed on 23 April between Charles, Count of Artois, and the allies. The treaty set the borders for France under the House of Bourbon and restored territories to other nations.', 1814, 5, 30, NULL, NULL, NULL, 'day', '30 May 1814', 73, 'https://en.wikipedia.org/wiki/Treaty_of_Paris_(1814)'),
  ('Q622774', 'French Revolution of 1848', 'The French Revolution of 1848 (French: Révolution française de 1848), also known as the February Revolution (Révolution de février), was a period of civil unrest in France, in February 1848, that led to the collapse of the July Monarchy and the foundation of the French Second Republic. It sparked the wave of revolutions of 1848.', 1848, 2, 25, 1848, 12, 2, 'day', '25 February 1848 – 2 December 1848', 76, 'https://en.wikipedia.org/wiki/French_Revolution_of_1848'),
  ('Q319260', 'Treaty of Paris', 'The Treaty of Paris of 1856, signed on 30 March 1856 at the Congress of Paris, brought an end to the Crimean War (1853–1856) between the Russian Empire and an alliance of the Ottoman Empire, the United Kingdom, the Second French Empire and the Kingdom of Sardinia. The treaty diminished Russian influence in the region.', 1856, 3, 30, NULL, NULL, NULL, 'day', '30 March 1856', 75, 'https://en.wikipedia.org/wiki/Treaty_of_Paris_(1856)'),
  ('Q46083', 'Franco-Prussian War', 'The Franco-Prussian War, occasionally known as the Franco-German War, and sometimes referred to in France as the War of 1870, was a conflict between France and the North German Confederation led by Prussia. Lasting from 19 July 1870 to 28 January 1871, the conflict was caused primarily by France''s determination to reassert its dominant position in continental Europe, which appeared in question following the decisive Prussian victory over Austria in 1866.', 1870, 7, 19, 1871, 1, 28, 'day', '19 July 1870 – 28 January 1871', 87, 'https://en.wikipedia.org/wiki/Franco-Prussian_War'),
  ('Q156681', 'Battle of Sedan', 'The Battle of Sedan, also known as the First Battle of Sedan, was fought during the Franco-Prussian War from 1 to 2 September 1870. Resulting in the capture of Emperor Napoleon III and over a hundred thousand troops, it effectively decided the war in favour of Prussia and its allies; however, fighting continued under a new French government.', 1870, 9, 1, 1870, 9, 2, 'day', '1 September 1870 – 2 September 1870', 74, 'https://en.wikipedia.org/wiki/Battle_of_Sedan'),
  ('Q847137', 'Treaty of Paris (1898)', 'The Treaty of Peace between the United States of America and the Kingdom of Spain, commonly known as the Treaty of Paris of 1898, was signed by Spain and the United States on December 10, 1898, and marked the official end of the Spanish–American War. Under it, Spain relinquished all claim of sovereignty over the West Indies archipelagos and islands of Cuba and Puerto Rico in the Caribbean, the Western Pacific island of Guam in the Mariana Islands in Micronesia, and the Western Pacific archipelago of the Philippines in Southeast Asia to the United States.', 1898, 12, 10, NULL, NULL, NULL, 'day', '10 December 1898', 72, 'https://en.wikipedia.org/wiki/Treaty_of_Paris_(1898)'),
  ('Q190712', 'First Battle of the Marne', 'The First Battle of the Marne or known in France as the Miracle on the Marne (French: miracle de la Marne) was a battle of the First World War fought from 5 to 12 September 1914. The German army invaded France with a plan for winning the war in 40 days by occupying Paris and destroying the French and British armies.', 1914, 9, 8, 1914, 9, 12, 'day', '8 September 1914 – 12 September 1914', 77, 'https://en.wikipedia.org/wiki/First_Battle_of_the_Marne'),
  ('Q130847', 'Battle of Verdun', 'The Battle of Verdun (French: Bataille de Verdun [bataj də vɛʁdœ̃]; German: Schlacht um Verdun [ʃlaxt ʔʊm ˈvɛɐ̯dœ̃]) was fought from 21 February to 18 December 1916 on the Western Front in France. The battle was the longest of the First World War and took place on the hills north of Verdun.', 1916, 2, 21, 1916, 12, 18, 'day', '21 February 1916 – 18 December 1916', 81, 'https://en.wikipedia.org/wiki/Battle_of_Verdun'),
  ('Q132568', 'Battle of the Somme', 'The Battle of the Somme (French: Bataille de la Somme; German: Schlacht an der Somme), also known as the Somme offensive, was a battle of the First World War fought by the armies of the British Empire and the French Republic against the German Empire. It took place between 1 July and 18 November 1916 on both sides of the upper reaches of the river Somme in France.', 1916, 7, 1, 1916, 11, 17, 'day', '1 July 1916 – 17 November 1916', 80, 'https://en.wikipedia.org/wiki/Battle_of_the_Somme'),
  ('Q654374', 'Battle of Cambrai', 'The Battle of Cambrai (Battle of Cambrai, 1917, First Battle of Cambrai and Schlacht von Cambrai) was a British attack in the First World War, followed by the biggest German counter-attack against the British Expeditionary Force (BEF) since 1914. The town of Cambrai, in the département of Nord, in France, was an important supply centre for the German Siegfriedstellung (known to the British as the Hindenburg Line) and capture of the town and the nearby Bourlon Ridge would threaten the rear of the German line to the north.', 1917, 11, 20, 1917, 12, 8, 'day', '20 November 1917 – 8 December 1917', 71, 'https://en.wikipedia.org/wiki/Battle_of_Cambrai_(1917)'),
  ('Q750567', 'Spring Offensive', 'The German spring offensive, also known as Kaiserschlacht ("Emperor''s Battle") or the Ludendorff offensive, was a series of German attacks along the Western Front during the First World War, beginning on 21 March 1918. Following the American entry into the war in April 1917, the Germans decided that their only remaining chance of victory was to defeat the Allies before the United States could ship soldiers across the Atlantic and fully deploy its resources.', 1918, 3, 21, 1918, 7, 18, 'day', '21 March 1918 – 18 July 1918', 70, 'https://en.wikipedia.org/wiki/German_spring_offensive'),
  ('Q1130507', 'Hundred Days Offensive', 'The Hundred Days Offensive (8 August to 11 November 1918) was a series of massive Allied offensives that ended the First World War. Beginning with the Battle of Amiens (8–12 August) on the Western Front, the Allies pushed the Imperial German Army back, undoing its gains from the German spring offensive (21 March – 18 July).', 1918, 11, 11, 1918, 11, 11, 'day', '11 November 1918', 69, 'https://en.wikipedia.org/wiki/Hundred_Days_Offensive'),
  ('Q8736', 'Treaty of Versailles', 'The Treaty of Versailles was a peace treaty signed on 28 June 1919. As the most important treaty of World War I, it ended the state of war between Germany and most of the Allied Powers.', 1919, 6, 28, NULL, NULL, NULL, 'day', '28 June 1919', 92, 'https://en.wikipedia.org/wiki/Treaty_of_Versailles'),
  ('Q269267', 'Treaty of Neuilly-sur-Seine', 'The Treaty of Neuilly-sur-Seine (French: Traité de Neuilly-sur-Seine; Bulgarian: Ньойски договор, romanized: Noĭski dogovor) was a treaty between the victorious Allies of World War I on the one hand, and Bulgaria, one of the defeated Central Powers in World War I, on the other. The treaty required Bulgaria to cede various territories.', 1919, 11, 27, NULL, NULL, NULL, 'day', '27 November 1919', 73, 'https://en.wikipedia.org/wiki/Treaty_of_Neuilly-sur-Seine'),
  ('Q181902', 'Treaty of Trianon', 'The Treaty of Trianon (French: Traité de Trianon; Hungarian: Trianoni békediktátum; Italian: Trattato del Trianon; Romanian: Tratatul de la Trianon), often referred to in Hungary as the Peace Dictate of Trianon or Dictate of Trianon, was prepared at the Paris Peace Conference. It was signed in the Grand Trianon at Versailles on 4 June 1920, and formally terminated World War I between most of the Allies of World War I and the Kingdom of Hungary.', 1920, 6, 4, NULL, NULL, NULL, 'day', '4 June 1920', 80, 'https://en.wikipedia.org/wiki/Treaty_of_Trianon'),
  ('Q182515', 'Treaty of Sèvres', 'The Treaty of Sèvres (French: Traité de Sèvres) was a 1920 treaty signed between some of the Allies of World War I and the Ottoman Empire, but not ratified. The treaty would have required the cession of large parts of Ottoman territory to France, the United Kingdom, Greece, and Italy, as well as creating large occupation zones within the Ottoman Empire.', 1920, 8, 10, NULL, NULL, NULL, 'day', '10 August 1920', 80, 'https://en.wikipedia.org/wiki/Treaty_of_S%C3%A8vres'),
  ('Q205073', 'Kellogg-Briand pact', 'The Kellogg–Briand Pact or Pact of Paris (officially the General Treaty for Renunciation of War as an Instrument of National Policy) is a 1928 international agreement on peace in which signatory states promised not to use war to resolve "disputes or conflicts of whatever nature or of whatever origin they may be, which may arise among them". The pact was signed by Germany, France, and the United States on 27 August 1928, and by most other states soon after.', 1928, 8, 27, NULL, NULL, NULL, 'day', '27 August 1928', 78, 'https://en.wikipedia.org/wiki/Kellogg%E2%80%93Briand_Pact'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q190882', 'Phoney War', 'The Phoney War was an eight-month period at the outset of World War II, lasting from September 1939 to May 1940, during which there were virtually no major Allied military land operations on the Western Front. World War II began on 1 September 1939 with Germany''s invasion of Poland.', 1939, 9, 3, 1940, 4, 10, 'day', '3 September 1939 – 10 April 1940', 77, 'https://en.wikipedia.org/wiki/Phoney_War'),
  ('Q170360', 'Armistice of 22 June 1940', 'The Armistice of 22 June 1940 (French: Armistice du 22 juin 1940; German: Waffenstillstand vom 22. Juni), sometimes referred to as the Second Armistice at Compiègne, was an agreement signed at 18:36 on 22 June 1940 near Compiègne, France, by officials of Nazi Germany and the French Third Republic.', 1940, 6, 22, NULL, NULL, NULL, 'day', '22 June 1940', 71, 'https://en.wikipedia.org/wiki/Armistice_of_22_June_1940'),
  ('Q208529', 'Battle of Dunkirk', 'The Battle of Dunkirk (French: Bataille de Dunkerque) was fought around the French port of Dunkirk (Dunkerque) during the Second World War, between the Allies and Nazi Germany. As the Allies were losing the Battle of France on the Western Front, the Battle of Dunkirk was the defence and evacuation of British and other Allied forces to Britain from 26 May to 4 June 1940.', 1940, 5, 26, 1940, 6, 4, 'day', '26 May 1940 – 4 June 1940', 75, 'https://en.wikipedia.org/wiki/Battle_of_Dunkirk'),
  ('Q911972', 'Dunkirk evacuation', 'In the Dunkirk evacuation, codenamed Operation Dynamo and also known as the Miracle of Dunkirk, or just Dunkirk, more than 338,000 Allied soldiers were evacuated during the Second World War from the beaches and harbour of Dunkirk in northern France between 26 May and 4 June 1940. The operation began after large numbers of Belgian, British, and French troops (as well as smaller contingents of Dutch and Polish soldiers) were cut off and surrounded by German troops during the six-week Battle of France.', 1940, 6, 4, 1940, 6, 4, 'day', '4 June 1940', 76, 'https://en.wikipedia.org/wiki/Dunkirk_evacuation'),
  ('Q2748708', 'German military administration in occupied France during World War II', 'The Military Administration in France was an interim occupation authority established by Nazi Germany during World War II to administer the occupied zone in areas of northern and western France. This so-called zone occupée was established in June 1940, and renamed zone nord ("north zone") in November 1942, when the previously unoccupied zone in the south known as zone libre ("free zone") was also occupied and renamed zone sud ("south zone").', 1940, 6, 22, 1944, 8, NULL, 'day', '22 June 1940 – August 1944', 68, 'https://en.wikipedia.org/wiki/German_military_administration_in_occupied_France_during_World_War_II'),
  ('Q270517', 'Dieppe Raid', 'Operation Jubilee or the Dieppe Raid (19 August 1942) was an Allied amphibious attack on the German-occupied port of Dieppe in northern France, during the Second World War. Over 6,050 infantry, predominantly Canadian, supported by a Canadian tank regiment, were landed by a Royal Navy task force under cover of the Royal Air Force and Royal Canadian Air Force.', 1942, 8, 19, NULL, NULL, NULL, 'day', '19 August 1942', 72, 'https://en.wikipedia.org/wiki/Dieppe_Raid'),
  ('Q16470', 'Normandy landings', 'The Normandy landings were the landing operations and associated airborne operations on 6 June 1944 of the Allied invasion of Normandy in Operation Overlord during the Second World War. Codenamed Operation Neptune and often referred to as D-Day (after the military term), it is the largest seaborne invasion in history.', 1944, 6, 6, 1944, 8, 29, 'day', '6 June 1944 – 29 August 1944', 81, 'https://en.wikipedia.org/wiki/Normandy_landings'),
  ('Q151018', 'Battle of the Bulge', 'The Battle of the Bulge, also known as the Ardennes Offensive and referred to by the Germans as Unternehmen Wacht am Rhein (transl. Operation Watch on the Rhine), was an offensive campaign on the Western Front during the Second World War, taking place from 16 December 1944 to 25 January 1945. It was launched through the densely forested Ardennes region of eastern Belgium and northern Luxembourg and was intended to stop Allied use of the Belgian port of Antwerp and to split the Allied lines, allowing the Germans to encircle and destroy each of the four Allied armies and force the western…', 1944, 12, 16, 1945, 1, 25, 'day', '16 December 1944 – 25 January 1945', 79, 'https://en.wikipedia.org/wiki/Battle_of_the_Bulge'),
  ('Q221111', 'Operation Dragoon', 'Operation Dragoon (initially Operation Anvil), known as Débarquement de Provence in French (lit. ''Provence Landing''), was the code name for the landing operation of the Allied invasion of Provence (Southern France) on 15 August 1944. Although initially designed to be executed in conjunction with Operation Overlord, the June 1944 Allied landing in Normandy, insufficient resources led to the cancellation of the second landing.', 1944, 9, 14, 1944, 9, 14, 'day', '14 September 1944', 71, 'https://en.wikipedia.org/wiki/Operation_Dragoon'),
  ('Q696835', 'Liberation of Paris', 'The Liberation of Paris (French: Libération de Paris) was a battle that took place during World War II from 19 August 1944 until the German garrison surrendered the French capital on 25 August 1944. Paris had been occupied by Nazi Germany since the signing of the Armistice of 22 June 1940, after which the Wehrmacht occupied northern and western France.', 1944, 8, 19, 1944, 8, 25, 'day', '19 August 1944 – 25 August 1944', 73, 'https://en.wikipedia.org/wiki/Liberation_of_Paris'),
  ('Q322943', 'Paris Peace Treaties', 'The Paris Peace Treaties (French: Traités de Paris) were signed on 10 February 1947 following the end of World War II in 1945. The Paris Peace Conference lasted from 29 July until 15 October 1946.', 1947, 2, 10, NULL, NULL, NULL, 'day', '10 February 1947', 72, 'https://en.wikipedia.org/wiki/Paris_Peace_Treaties%2C_1947'),
  ('Q274811', 'Élysée Treaty', 'The Élysée Treaty was a treaty of friendship between France and West Germany, signed by President Charles de Gaulle and Chancellor Konrad Adenauer on 22 January 1963 at the Élysée Palace in Paris. With the signing of this treaty, Germany and France established a new foundation for relations, bringing an end to centuries of French–German enmity and wars.', 1963, 1, 22, NULL, NULL, NULL, 'day', '22 January 1963', 68, 'https://en.wikipedia.org/wiki/%C3%89lys%C3%A9e_Treaty'),
  ('Q6743', 'May 68', 'May 68 (French: Mai 68) was a period of protests, riots, strikes, and civil unrest in France, that began in May 1968, and became one of the most significant social uprisings in modern European history. Sparked by student demonstrations against university conditions and government repression, the movement escalated into a nationwide general strike involving millions of workers, bringing the country to the brink of revolution.', 1968, NULL, NULL, 1968, 6, 23, 'year', '1968', 81, 'https://en.wikipedia.org/wiki/May_68'),
  ('Q696802', 'Paris Peace Accords', 'The Paris Peace Accords (Vietnamese: Hiệp định Paris về Việt Nam, lit. ''Paris Treaty about Vietnam''), officially the Agreement on ending the war and restoring peace in Viet-Nam (Hiệp định về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam), was a peace agreement signed on 27 January 1973 to establish peace in Vietnam and end the Vietnam War. It included a main treaty and accompanying annexes.', 1973, 1, 27, NULL, NULL, NULL, 'day', '27 January 1973', 68, 'https://en.wikipedia.org/wiki/Paris_Peace_Accords'),
  ('Q462716', 'Turkish Airlines Flight 981', 'Turkish Airlines Flight 981 was a scheduled flight from Istanbul Yeşilköy Airport to London Heathrow Airport, with an intermediate stop at Orly Airport in Paris. On 3 March 1974, the McDonnell Douglas DC-10 operating the flight crashed into the Ermenonville Forest, about 40 kilometres (25 mi; 22 nmi) outside Paris, killing all 335 passengers and 11 crew.', 1974, 3, 3, NULL, NULL, NULL, 'day', '3 March 1974', 68, 'https://en.wikipedia.org/wiki/Turkish_Airlines_Flight_981'),
  ('Q406535', 'Air France Flight 4590', 'Air France Flight 4590 was an international charter flight from Paris to New York. On 25 July 2000, a Concorde passenger jet operating the flight crashed shortly after takeoff, killing all 109 people on board and four on the ground.', 2000, 7, 25, NULL, NULL, NULL, 'day', '25 July 2000', 70, 'https://en.wikipedia.org/wiki/Air_France_Flight_4590'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q18718876', 'Charlie Hebdo shooting', 'On 7 January 2015, at about 11:30 a.m. in Paris, France, the employees of the French satirical weekly magazine Charlie Hebdo were targeted in a terrorist shooting attack by two French-born Algerian Muslim brothers, Saïd and Chérif Kouachi.', 2015, 1, 7, NULL, NULL, NULL, 'day', '7 January 2015', 82, 'https://en.wikipedia.org/wiki/Charlie_Hebdo_shooting'),
  ('Q21707860', 'Paris Agreement', 'The Paris Agreement (also called the Paris Accords or Paris Climate Accords) is an international treaty on climate change that was signed in 2016. The treaty covers climate change mitigation, adaptation, and finance.', 2015, 12, 12, NULL, NULL, NULL, 'day', '12 December 2015', 85, 'https://en.wikipedia.org/wiki/Paris_Agreement'),
  ('Q25893254', '2016 Nice attack', 'On the evening of 14 July 2016, a 19-tonne cargo truck was deliberately driven into crowds of people celebrating Bastille Day on the Promenade des Anglais in Nice, France, resulting in the deaths of 86 people and injuring 458 others. The driver was Mohamed Lahouaiej-Bouhlel, a Tunisian living in France.', 2016, 7, 14, NULL, NULL, NULL, 'day', '14 July 2016', 81, 'https://en.wikipedia.org/wiki/2016_Nice_truck_attack'),
  ('Q58805164', 'Yellow vests movement', 'The yellow vest movement (French: Mouvement des gilets jaunes, pronounced [muvmɑ̃ de ʒilɛ ʒon]) refers to those involved in a series of populist, grassroots weekly protests in France that began on 17 November 2018 and ended on 28 June 2020. After an online petition posted in May 2018 had attracted nearly one million signatures, mass demonstrations began on 17 November.', 2018, 11, 17, NULL, NULL, NULL, 'day', '17 November 2018', 80, 'https://en.wikipedia.org/wiki/Yellow_vests_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q100437698', 'murder of Samuel Paty', 'On 16 October 2020, Samuel Paty (French: [samɥɛl pati]), a French secondary school teacher, was attacked and killed in Éragny, Val-d''Oise, Île-de-France, France, by an Islamist terrorist. The perpetrator, Abdoullakh Abouyezidovich Anzorov, an 18-year-old Russian Muslim refugee, killed and beheaded Paty with a cleaver, and was shot and killed by police minutes later.', 2020, 10, 16, NULL, NULL, NULL, 'day', '16 October 2020', 71, 'https://en.wikipedia.org/wiki/Murder_of_Samuel_Paty'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods');
